+        services: services(extension: yoclip),
+      );
+      // Core tool list identical; the extension appends exactly itself.
+      expect(
+        extended.tools.map((t) => t.name),
+        [...plain.tools.map((t) => t.name), 'yoclip_cut'],
+      );
