+          'registered by both $previous and $registrant — the builder '
+          'never silently replaces a tool; rename one of the two.',
+        );
+      }
+      owner[tool.name] = registrant;
+    }
+  }
+
+  for (final MapEntry(key: registrant, value: tools) in groups.entries) {
